window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b591713749e2b40d"]={"versions": [{"id": "FIG-b591713749e2b40d", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines atomaren Teilschritts innerhalb des End-to-End-Kommunikationsschutzes (AUTOSAR E2E Protocol, Profil 4). Das Diagramm detailliert den Teilschritt „Read Counter“ innerhalb der Prüffunktion <code>E2E_P04Check()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontext / Funktion</strong>: <code>E2E_P04Check()</code> (gekennzeichnet oben links als Unterprozess bzw. Funktionskontext).\n</li><li><strong>Eingangsdaten / Array</strong>: Eingabepuffer <code>Data[]</code> mit Byte-Offset <code>Offset</code>.\n</li><li><strong>Lokale Variable</strong>: <code>ReceivedCounter</code> vom Datentyp <code>uint16</code>.\n</li><li><strong>Knotenelemente</strong>: Ein Startknoten (Initial Node, ausgefüllter Kreis), ein Aktionsknoten (Action State) sowie ein Endknoten (Activity Final Node, Stopp-Symbol bzw. Doppelkreis mit gefülltem Zentrum).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Ausführung beginnt am Startknoten der Aktivität.\n</li><li>Der Kontrollfluss geht über eine Transition direkt in den Aktionsknoten über: Es werden zwei Bytes aus dem Eingangsdatenarray <code>Data[Offset+2...Offset+3]</code> in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) extrahiert und der lokalen Variable <code>ReceivedCounter</code> (<code>uint16</code>) zugewiesen.\n</li><li>Nach Abschluss der Zuweisung führt der Kontrollfluss zum Aktivitätsendknoten und schließt diesen Teilschritt ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Verbindlichkeit</strong>: Das Diagramm definiert das verbindliche Verhalten für die Implementierung der Funktion <code>E2E_P04Check()</code> bei der Extraktion des Sequenzzählers gemäß Anforderung <code>[PRS_E2E_00358]</code>.\n</li><li><strong>Endianness &amp; Adressierung</strong>: Die Auswertung muss zwingend in Big-Endian-Reihenfolge (<code>Data[Offset+2]</code> als höherwertiges Byte, <code>Data[Offset+3]</code> als niederwertiges Byte) erfolgen, unabhängig von der nativen Prozessorarchitektur.\n</li><li><strong>Speicherzugriff</strong>: Entwickler müssen sicherstellen, dass das übergebene Datenarray <code>Data</code> mindestens eine Länge von <code>Offset + 4</code> aufweist, um Pufferüberläufe beim Zugriff auf die Indizes <code>Offset+2</code> und <code>Offset+3</code> zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-66d92d1970316a66", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines atomaren Teilschritts innerhalb des End-to-End-Kommunikationsschutzes (AUTOSAR E2E Protocol, Profil 4). Das Diagramm detailliert den Teilschritt „Read Counter“ innerhalb der Prüffunktion <code>E2E_P04Check()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontext / Funktion</strong>: <code>E2E_P04Check()</code> (gekennzeichnet oben links als Unterprozess bzw. Funktionskontext).\n</li><li><strong>Eingangsdaten / Array</strong>: Eingabepuffer <code>Data[]</code> mit Byte-Offset <code>Offset</code>.\n</li><li><strong>Lokale Variable</strong>: <code>ReceivedCounter</code> vom Datentyp <code>uint16</code>.\n</li><li><strong>Knotenelemente</strong>: Ein Startknoten (Initial Node, ausgefüllter Kreis), ein Aktionsknoten (Action State) sowie ein Endknoten (Activity Final Node, Stopp-Symbol bzw. Doppelkreis mit gefülltem Zentrum).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Ausführung beginnt am Startknoten der Aktivität.\n</li><li>Der Kontrollfluss geht über eine Transition direkt in den Aktionsknoten über: Es werden zwei Bytes aus dem Eingangsdatenarray <code>Data[Offset+2...Offset+3]</code> in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) extrahiert und der lokalen Variable <code>ReceivedCounter</code> (<code>uint16</code>) zugewiesen.\n</li><li>Nach Abschluss der Zuweisung führt der Kontrollfluss zum Aktivitätsendknoten und schließt diesen Teilschritt ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Verbindlichkeit</strong>: Das Diagramm definiert das verbindliche Verhalten für die Implementierung der Funktion <code>E2E_P04Check()</code> bei der Extraktion des Sequenzzählers gemäß Anforderung <code>[PRS_E2E_00358]</code>.\n</li><li><strong>Endianness &amp; Adressierung</strong>: Die Auswertung muss zwingend in Big-Endian-Reihenfolge (<code>Data[Offset+2]</code> als höherwertiges Byte, <code>Data[Offset+3]</code> als niederwertiges Byte) erfolgen, unabhängig von der nativen Prozessorarchitektur.\n</li><li><strong>Speicherzugriff</strong>: Entwickler müssen sicherstellen, dass das übergebene Datenarray <code>Data</code> mindestens eine Länge von <code>Offset + 4</code> aufweist, um Pufferüberläufe beim Zugriff auf die Indizes <code>Offset+2</code> und <code>Offset+3</code> zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-05f3bdcd61cf00d4", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm im Kontext der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection Protocol). Dargestellt ist der interne Teilschritt „Read Counter“ der Prüffunktion <code>E2E_P44Check()</code> für das E2E-Profil 44. Das Diagramm spezifiziert die Extraktion des Sequenzzählers aus dem empfangenen Datenstrom auf Empfängerseite vor der anschließenden Plausibilisierung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Aufrufende Funktion / Kontext: <code>E2E_P44Check()</code>\n</li><li>Datenstrukturen und Puffer: Byte-Array <code>Data[]</code>, parametriert über einen Startversatz <code>Offset</code>\n</li><li>Lokale Variablen: <code>ReceivedCounter</code> vom Datentyp <code>uint16</code>\n</li><li>Knoten des Aktivitätsdiagramms: Initialknoten (Startknoten), Aktionsknoten („Copy bytes Data[Offset+2...Offset+3] in Big Endian order on uint16 local variable ReceivedCounter“) und Aktivitätsendknoten (Endknoten)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Kontrollfluss beginnt am Initialknoten der Aktivität <code>E2E_P44Check()</code>.\n</li><li>Im Aktionsknoten werden die zwei aufeinanderfolgenden Bytes an den Positionen <code>Offset + 2</code> und <code>Offset + 3</code> aus dem Byte-Array <code>Data</code> ausgelesen und in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in die 16-Bit breite lokale Variable <code>ReceivedCounter</code> übernommen.\n</li><li>Nach Abschluss der Zuweisung geht der Kontrollfluss direkt in den Aktivitätsendknoten über.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Spezifiziert das normierte Deserialisierungsformat des 16-Bit-Zählers für Profil 44: Fester Offset von 2 Bytes relativ zum konfigurierten Basis-Offset (<code>Offset+2</code> und <code>Offset+3</code>) sowie Big-Endian-Kodierung (Network Byte Order).\n</li><li>Für die Software-Implementierung von <code>E2E_P44Check()</code> ist sicherzustellen, dass die Variable <code>ReceivedCounter</code> vor Überlauf und Fehlinterpretation geschützt als vorzeichenloser 16-Bit-Ganzzahlwert (<code>uint16</code>) verarbeitet wird.\n</li><li>Vor dem Byte-Zugriff muss gewährleistet sein, dass der Datenpuffer mindestens eine Länge von <code>Offset + 4</code> Bytes aufweist, um Pufferüberläufe zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d126dc911ce030fc", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm im Kontext der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection Protocol). Dargestellt ist der interne Teilschritt „Read Counter“ der Prüffunktion <code>E2E_P04Check()</code> für das E2E-Profil 4. Das Diagramm spezifiziert die Extraktion des Sequenzzählers aus dem empfangenen Datenstrom auf Empfängerseite vor der anschließenden Plausibilisierung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Aufrufende Funktion / Kontext: <code>E2E_P04Check()</code>\n</li><li>Datenstrukturen und Puffer: Byte-Array <code>Data[]</code>, parametriert über einen Startversatz <code>Offset</code>\n</li><li>Lokale Variablen: <code>ReceivedCounter</code> vom Datentyp <code>uint16</code>\n</li><li>Knoten des Aktivitätsdiagramms: Initialknoten (Startknoten), Aktionsknoten („Copy bytes Data[Offset+2...Offset+3] in Big Endian order on uint16 local variable ReceivedCounter“) und Aktivitätsendknoten (Endknoten)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Kontrollfluss beginnt am Initialknoten der Aktivität <code>E2E_P04Check()</code>.\n</li><li>Im Aktionsknoten werden die zwei aufeinanderfolgenden Bytes an den Positionen <code>Offset + 2</code> und <code>Offset + 3</code> aus dem Byte-Array <code>Data</code> ausgelesen und in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in die 16-Bit breite lokale Variable <code>ReceivedCounter</code> übernommen.\n</li><li>Nach Abschluss der Zuweisung geht der Kontrollfluss direkt in den Aktivitätsendknoten über.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Spezifiziert das normierte Deserialisierungsformat des 16-Bit-Zählers für Profil 4: Fester Offset von 2 Bytes relativ zum konfigurierten Basis-Offset (<code>Offset+2</code> und <code>Offset+3</code>) sowie Big-Endian-Kodierung (Network Byte Order).\n</li><li>Für die Software-Implementierung von <code>E2E_P04Check()</code> ist sicherzustellen, dass die Variable <code>ReceivedCounter</code> vor Überlauf und Fehlinterpretation geschützt als vorzeichenloser 16-Bit-Ganzzahlwert (<code>uint16</code>) verarbeitet wird.\n</li><li>Vor dem Byte-Zugriff muss gewährleistet sein, dass der Datenpuffer mindestens eine Länge von <code>Offset + 4</code> Bytes aufweist, um Pufferüberläufe zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-b591713749e2b40d", "to": "FIG-66d92d1970316a66", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
